Certainly! Here's the updated `tweetsSlice.js` with middleware, specifically using the `createAsyncThunk` utility provided by Redux Toolkit to handle async actions like fetching data from an API:

```jsx
import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import GlobalConstants from "../../common/globalConstants";

// Define the initial state
const initialState = {
  tweets: [],
  status: "idle",
  error: null,
};

// Async thunk for fetching tweets
export const fetchTweets = createAsyncThunk("tweets/fetchTweets", async () => {
  const BASE_URL = GlobalConstants.tweetsApplicationBaseURL;
  const response = await fetch(`${BASE_URL}/tweets`);
  const data = await response.json();
  return data;
});

// Create a slice with initial state and reducers
const tweetsSlice = createSlice({
  name: "tweets",
  initialState,
  reducers: {
    addTweet: (state, action) => {
      state.tweets.push(action.payload);
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchTweets.pending, (state) => {
        state.status = "loading";
      })
      .addCase(fetchTweets.fulfilled, (state, action) => {
        state.status = "succeeded";
        state.tweets = action.payload;
      })
      .addCase(fetchTweets.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      });
  },
});

// Export the actions
export const { addTweet } = tweetsSlice.actions;

// Export the reducer
export default tweetsSlice.reducer;
```

This updated slice includes the use of `createAsyncThunk` for fetching tweets asynchronously. It also handles the loading, success, and error states using `extraReducers`. Remember to update the import path for `GlobalConstants` and adjust any other details according to your application structure.

