// Create an Express app
const app = express();

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/tweetapp', {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// Define a Tweet schema
const tweetSchema = new mongoose.Schema({
  content: String,
  comments: [{
    text: String,
    nestedComments: [{
      text: String,
    }],
  }],
});

// Create a Tweet model
const Tweet = mongoose.model('Tweet', tweetSchema);

// Middleware to parse JSON
app.use(express.json());

// Route to get all tweets
app.get('/tweets', async (req, res) => {
  try {
    const tweets = await Tweet.find();
    res.json(tweets);
  } catch (error) {
    res.status(500).json({ error: 'Error fetching tweets' });
  }
});

// Route to create a new tweet
app.post('/tweets', async (req, res) => {
  try {
    const newTweet = new Tweet(req.body);
    await newTweet.save();
    res.status(201).json(newTweet);
  } catch (error) {
    res.status(400).json({ error: 'Error creating tweet' });
  }
});

