        AmazonS3 s3Client = AmazonS3ClientBuilder.standard()
                .withRegion("your-aws-region")
                .withCredentials(new AWSStaticCredentialsProvider(
                        new BasicAWSCredentials("your-access-key", "your-secret-key")))
                .build();

