```java
import java.text.SimpleDateFormat;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.temporal.IsoFields;
import java.util.Calendar;
import java.util.Date;

public class RecurrenceExample {

    private static final DateTimeFormatter MONTH_YEAR_FORMATTER = DateTimeFormatter.ofPattern("MMM yyyy");
    private static final DateTimeFormatter DAY_MONTH_YEAR_FORMATTER = DateTimeFormatter.ofPattern("dd MMM yyyy");

    private String getIterationName(Recurrence recurrence, Date triggerDate) {
        String name = "";
        switch (recurrence) {
            case MONTHLY -> {
                Calendar calendar = Calendar.getInstance();
                calendar.setTime(triggerDate);
                name = MONTH_YEAR_FORMATTER.format(calendar.toInstant());
                return name;
            }
            case DAILY -> {
                Calendar calendar = Calendar.getInstance();
                calendar.setTime(triggerDate);
                name = DAY_MONTH_YEAR_FORMATTER.format(calendar.toInstant());
                return name;
            }
            case QUARTERLY, ANNUALLY, BIANNUALLY -> {
                LocalDate localDate = Instant.ofEpochMilli(triggerDate.getTime())
                        .atZone(ZoneId.systemDefault())
                        .toLocalDate();
                if (recurrence == Recurrence.QUARTERLY) {
                    int quarter = localDate.get(IsoFields.QUARTER_OF_YEAR);
                    name = "Q" + quarter + " " + localDate.getYear();
                } else if (recurrence == Recurrence.ANNUALLY) {
                    name = "Year_" + localDate.getYear();
                } else if (recurrence == Recurrence.BIANNUALLY) {
                    int month = localDate.getMonthValue();
                    name = (month <= 5 ? "First half " : "Second Half ") + localDate.getYear();
                }
                return name;
            }
            case BIMONTHLY -> {
                LocalDate currentDate = Instant.ofEpochMilli(triggerDate.getTime())
                        .atZone(ZoneId.systemDefault())
                        .toLocalDate();
                LocalDate firstDayOfMonth = currentDate.withDayOfMonth(1);
                int lastDayOfMonth = currentDate.lengthOfMonth();
                LocalDate middleOfMonth = firstDayOfMonth.plusDays(lastDayOfMonth / 2);

