import React from 'react';
import './form-message.css';

const FormMessageTypes = {
    Success: 'success',
    Warning: 'warning',
    FormValidation: 'Form Validation',
    APIResponseError: 'API Response Error',
};

const FormMessage = ({ formErrors = [] }) => {
    const getClassName = (errorType) => {
        switch (errorType) {
            case FormMessageTypes.Success:
                return 'form-message-item form-message-success';
            case FormMessageTypes.Warning:
                return 'form-message-item form-message-warning';
            case FormMessageTypes.FormValidation:
                return 'form-message-item form-message-validation';
            case FormMessageTypes.APIResponseError:
                return 'form-message-item form-message-api-error';
            default:
                return 'form-message-item';
        }
    };

    return (
        formErrors.length > 0 && (
            <div className="form-message-container">
                {formErrors.map(({ errorType, message }, index) => (
                    <div key={index} className={getClassName(errorType)}>
                        <span className="form-message-icon">
                            {errorType === FormMessageTypes.Success && '✅'}
                            {errorType === FormMessageTypes.Warning && '⚠️'}
                            {errorType === FormMessageTypes.FormValidation && '❌'}
                            {errorType === FormMessageTypes.APIResponseError && '🚫'}
                        </span>
                        <span className="form-message-text">{`${errorType}: ${message}`}</span>
