import React, { useEffect, useCallback, useRef } from "react";
import { FaTimes } from "react-icons/fa";
import './ModalV3_1.css';

const ModalV3 = ({ title, children, onClose }) => {
  const modalRef = useRef(null);

  // Handle 'Escape' key press to close the modal
  const handleEscKeyPress = useCallback((event) => {
    if (event.key === "Escape") {
      onClose();
    }
  }, [onClose]);

  // Attach and detach 'keydown' event listener
  useEffect(() => {
    document.addEventListener("keydown", handleEscKeyPress);
    return () => {
      document.removeEventListener("keydown", handleEscKeyPress);
    };
  }, [handleEscKeyPress]);

  // Make modal draggable
  useEffect(() => {
    const modal = modalRef.current;
    let isDragging = false, offsetX = 0, offsetY = 0;

    const onMouseDown = (e) => {
      isDragging = true;
      offsetX = e.clientX - modal.getBoundingClientRect().left;
      offsetY = e.clientY - modal.getBoundingClientRect().top;
      document.addEventListener("mousemove", onMouseMove);
    };

    const onMouseMove = (e) => {
      if (isDragging) {
        modal.style.left = `${e.clientX - offsetX}px`;
        modal.style.top = `${e.clientY - offsetY}px`;
      }
    };

    const onMouseUp = () => {
      isDragging = false;
      document.removeEventListener("mousemove", onMouseMove);
    };

    modal.addEventListener("mousedown", onMouseDown);
    document.addEventListener("mouseup", onMouseUp);

    return () => {
      modal.removeEventListener("mousedown", onMouseDown);
      document.removeEventListener("mouseup", onMouseUp);
    };
  }, []);

  return (
    <>
      <div className="modal-backdrop" onClick={onClose}></div>
      <dialog open className="modal" ref={modalRef}>
        <div className="modal-header">
          <h2>{title || "Modal Title"}</h2>
