        const { path, element: Element, children, index: isIndexRoute } = route;

        return (
            <Route
                key={index}
                path={path}
                element={<Element />}
            >
                {children && generateRoutes(children)}
                {isIndexRoute && <Route index element={<Element />} />}
            </Route>
        );
