                type,
                result.months(), result.days(), result.years(), result.weeks(),
                totalYearsFromMonths, totalYearsFromDays, totalYearsFromWeeks
        );
    }

    private static double roundTo3Decimals(double value) {
        return Math.round(value * 1000.0) / 1000.0;
    }
