    const [searchParams] = useSearchParams();
    const areaParam = searchParams.get("area");

    // State for managing selected action title
    const [selectedActionTitle, setSelectedActionTitle] = useState(
        convertToCamelCase(areaParam) || null
    );

    // Navigation Function
    const navigateToArea = useCallback((area = '') => {
        navigate({
            pathname: '/playground',
            search: area ? createSearchParams({ area }).toString() : '',
        });
    }, [navigate]);

    // Component Rendering Based on Area
    const componentFromArea = useMemo(() => {
        const key = addSuffix(convertToCamelCase(areaParam));
        return PlaygroundArea[key] || <h1>Please Select Area</h1>;
    }, [areaParam]);

    // Action List for HoverActions
    const actions = Object.keys(PlaygroundArea).map((key, idx) => ({
        id: `action_${idx + 1}`,
        label: removeSuffix(key),
        onClick: () => navigateToArea(convertToKebabCase(removeSuffix(key))),
    }));

