    type = FieldValueType.SingleValue,
    label,
    value,
    renderItem = defaultItemRenderer,
}) => (
    <div className="card-field">
        <strong>{label}:</strong>{" "}
        {type === FieldValueType.ArrayValue ? (
            value?.length > 0 ? (
                <ul>
                    {value.map((item, index) => (
                        <li key={index}>{renderItem(item)}</li>
                    ))}
                </ul>
            ) : (
                <span>N/A</span>
            )
        ) : (
            renderItem(value)
        )}
    </div>
);

const Card = ({ title, fields = [] }) => {
    return (
        <div className="card">
            {title && (
                <div className="card-header">
                    <span>{title}</span>
                </div>
            )}
            <div className="card-body">
                {fields.length > 0 ? (
                    fields.map(({ type, label, value, renderItem }, idx) => (
                        <Field
                            key={idx}
                            type={type}
                            label={label}
                            value={value}
                            renderItem={renderItem}
                        />
                    ))
                ) : (
                    <span>No fields provided</span>
                )}
            </div>
        </div>
    );
};

const renderCard = ({ title, objectToBeRendered }) => {
    if (!objectToBeRendered || typeof objectToBeRendered !== "object") {
        return <>Invalid object provided for rendering into a card</>;
    }
    if (Array.isArray(objectToBeRendered)) {
        return <>Array value rendering into a card is currently not available</>;
    }

    const fields = Object.keys(objectToBeRendered).map((key) => ({
        type: Array.isArray(objectToBeRendered[key])
            ? FieldValueType.ArrayValue
            : FieldValueType.SingleValue,
        label: camelCaseToTitleCase(key),
        value: objectToBeRendered[key],
    }));

    return <Card title={title} fields={fields} />;
};

