    return () => {
      document.removeEventListener("keydown", handleEscKeyPress);
    };
  }, [handleEscKeyPress]);

  return (
    <>
      <div className={backdrop}></div>
      <dialog open className={modal}>
        <button
          className={closeButton}
          onClick={onClose}
          aria-label="Close modal"
        >
          <FaTimes />
        </button>
        {children}
      </dialog>
    </>
  );
};


