import React, { useMemo, useState } from 'react';
import { createSearchParams, useNavigate, useSearchParams } from 'react-router-dom';
import FormVersionsPlayground from './forms/FormVersionsPlayground';
import FormImplementationsPlayground from './forms/FormImplementationsPlayground';
import HoverActions from '../../common/components/HoverActions';

// Function to remove a specified suffix (default is 'Playground')
const removeSuffix = (input, suffix = 'Playground') => {
    if (!input || !suffix) return input;
    const suffixRegex = new RegExp(`${suffix}$`); // Create a regex to match the suffix at the end
    return input.replace(suffixRegex, '');
};

// Function to add a specified suffix to the input if it doesn't already end with it
const addSuffix = (input, suffix = 'Playground') => {
    if (!input || !suffix) return input;
    return input.endsWith(suffix) ? input : input + suffix;
};

// Function to convert a camel case string to kebab-case
function convertToKebabCase(input) {
    if (!input) return input;
    // const textWithoutSuffix = removeSuffix(input);
    return input
        .split(/(?=[A-Z])/) // Split before each uppercase letter
        .join('-')          // Join with a hyphen
        .toLowerCase();     // Convert to lowercase
}

// Function to convert a kebab-case string to CamelCase
function convertToCamelCase(input) {
    if (!input) return input;
    return input
        .split('-')                // Split by hyphen
        .map((word, index) =>
            // index === 0 ? word : word.charAt(0).toUpperCase() + word.slice(1)
            word.charAt(0).toUpperCase() + word.slice(1)
        ) // Capitalize each word
        .join('');                 // Join words back together
}

const PlaygroundArea = {
    FormVersionsPlayground: <FormVersionsPlayground />,
    FormImplementationsPlayground: <FormImplementationsPlayground />
}



const Playground = () => {
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const area = searchParams.get("area");
    const [selectedActionTitle, setSelectedActionTitle] = useState(convertToCamelCase(area) || null);
    const navigateToArea = (area = "") => {
        navigate({
            pathname: `/playground`,
            search: area
                ? createSearchParams({
                    area: area,
                }).toString()
                : "",
        })
    };
    const componentFromArea = useMemo(() => {
        const key = addSuffix(convertToCamelCase(area));
        return PlaygroundArea[key] || <h1>Please Select Area</h1>
    }, [area])
    const actions = Object.keys(PlaygroundArea).map((key, idx) => ({
        id: `action_${idx + 1}`,
        label: removeSuffix(key),
        onClick: () => navigateToArea(convertToKebabCase(removeSuffix(key)))
    }));
    return (
        <div>            
            <HoverActions
                actions={actions.map(({ id, label, onClick }) => (
                    <span key={id} onClick={() => {
                        setSelectedActionTitle(label);
                        onClick();
                    }}>
                        {label}
                    </span>
                ))}
                title={selectedActionTitle || 'Select Area'}
            />
            {componentFromArea}
        </div>
    )
}

export default Playground

