Sure, here's how you can create an Express application with two endpoints: one to save student data to MongoDB and another to display the list of saved students using EJS templates:

First, make sure you have MongoDB installed and running.

Then, install the necessary dependencies:

```bash
npm install express ejs mongoose body-parser
```

Now, create an `app.js` file with the following content:

```javascript
// Import required modules
const express = require('express');
const mongoose = require('mongoose');
const bodyParser = require('body-parser');

// Initialize Express application
const app = express();

// Set up EJS as the view engine
app.set('view engine', 'ejs');

// Set up body parser middleware
app.use(bodyParser.urlencoded({ extended: true }));

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/studentDB', {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// Create a Mongoose schema for student
const studentSchema = new mongoose.Schema({
  name: String,
  age: Number,
});

// Create a Mongoose model based on the schema
const Student = mongoose.model('Student', studentSchema);

// Define a route to display the form to save student data
app.get('/add', (req, res) => {
  res.render('addStudent');
});

// Define a route to handle the POST request to save student data
app.post('/add', (req, res) => {
  const { name, age } = req.body;

  // Create a new student instance
  const newStudent = new Student({
    name: name,
    age: age,
  });

  // Save the student to the database
  newStudent.save((err) => {
    if (err) {
      console.error(err);
      res.send('Error saving student');
    } else {
      res.redirect('/list');
    }
  });
});

// Define a route to display the list of saved students
app.get('/list', (req, res) => {
  // Retrieve all students from the database
  Student.find({}, (err, students) => {
    if (err) {
      console.error(err);
      res.send('Error fetching students');
    } else {
      res.render('studentList', { students: students });
    }
  });
});

// Start the server
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});
```

