import React, { useState, useEffect } from 'react';
import { useMutation, gql } from '@apollo/client';

// GraphQL mutation to upsert a resume
const UPSERT_RESUME = gql`
  mutation UpsertResume($resume: ResumeInput!) {
    upsertResume(resume: $resume) {
      uniqueId
      introduction
      summary
      companies {
        uniqueId
        name
        details
        projects {
          uniqueId
          name
          details
        }
      }
      educations {
        uniqueId
        name
        details
      }
    }
  }
`;

const ResumeForm = ({ addResume, resume }) => {
  // State for form inputs
  const [formData, setFormData] = useState({
    introduction: '',
    summary: '',
  });

  // Set initial form data if a resume is provided
  useEffect(() => {
    if (resume) {
      setFormData({
        introduction: resume.introduction || '',
        summary: resume.summary || '',
      });
    }
  }, [resume]);

  // Mutation hook for upserting a resume
  const [upsertResume] = useMutation(UPSERT_RESUME);

  // Function to handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      // Execute the mutation with form data
      const { data } = await upsertResume({
        variables: {
          resume: formData,
        },
      });

      // Add the new resume to the list
      addResume(data.upsertResume);

      // Reset form inputs
      setFormData({
        introduction: '',
        summary: '',
      });
    } catch (error) {
      console.error('Error creating or updating resume:', error);
    }
  };

  // Function to handle input changes
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="introduction">Introduction:</label>
        <input
          type="text"
          id="introduction"
          name="introduction"
          value={formData.introduction}
          onChange={handleInputChange}
        />
      </div>
      <div>
        <label htmlFor="summary">Summary:</label>
        <textarea
          id="summary"
          name="summary"
          value={formData.summary}
          onChange={handleInputChange}
        ></textarea>
      </div>
      <button type="submit">Save Resume</button>
    </form>
  );
};

export default ResumeForm;
