Your code looks quite close to the intended structure, but here are a few optimizations and corrections to improve its readability and functionality:

1. **Correct the spelling of `containsErrorMessages`** in both the function and its references.
2. **Refactor conditional checks** in `validateFields` to be clearer and more concise.
3. **Fix `validateFields` logic** to ensure that `children` field definitions are processed only if validation passes.

Here's an improved version with these fixes:

```javascript
// src\components\resumes-with-tree\common\validations-v2\validation-util.js
const ItemType = {
    RESUME: "resume",
    COMPANY: "company",
    PROJECT: "project",
};

const ValidationMessageType = {
    OK: "ok",
    WARNING: "warning",
    ERROR: "error",
};

// Utility functions for general type checks
const isUndefined = (value) => value === undefined;
const isObject = (value) => typeof value === "object" && !isUndefined(value);
const isString = (value) => typeof value === "string" && !isUndefined(value);
const isArray = (value) => Array.isArray(value);
const isArrayOfStrings = (array) => isArray(array) && array.every(isString);
const containsErrorMessages = (messages) =>
    messages.some((msg) => msg.type === ValidationMessageType.ERROR);

const validateFields = (obj, fieldDefs, messages, parentField = "") => {
    fieldDefs.forEach(({ field, type, isRequired, customValidation, children }) => {
        const value = obj[field];
        const fieldName = parentField ? `${parentField}.${field}` : field;

        // Required field check
        if (isRequired && isUndefined(value)) {
            messages.push({
                type: ValidationMessageType.ERROR,
                message: `Missing required field: ${fieldName}`,
            });
            return;
        }

        // Type validation
        const typeValidation = {
            string: isString,
            object: isObject,
            array: isArray,
        }[type];
        if (typeValidation && !typeValidation(value)) {
            messages.push({
                type: ValidationMessageType.ERROR,
                message: `Field '${fieldName}' should be a ${type}.`,
            });
            return;
        }

        // Custom validation
        if (customValidation) {
            const { passed, customValidationMessage } = customValidation(value);
            if (!passed) {
                messages.push({
                    type: ValidationMessageType.ERROR,
                    message: `Field '${fieldName}' ${customValidationMessage || "failed custom validation."}`,
                });
                return;
            }
        }

        // Children validation if no errors encountered so far
        if (!containsErrorMessages(messages) && isObject(value) && children && children.length > 0) {
            validateFields(value, children, messages, fieldName);
        }
    });
};

export {
    ItemType,
    validateFields,
    ValidationMessageType,
    isUndefined,
    isObject,
    isString,
    isArray,
    isArrayOfStrings,
    containsErrorMessages,
};
```

