        }
    };

    // Function to handle input changes
    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData({
            ...formData,
            [name]: value,
        });
    };

    return (
        <>
            <h3>{resume ? "Edit Resume" : "Add Resume"}</h3>
            <form onSubmit={handleSubmit}>
                <div>
                    <label htmlFor="introduction">Introduction:</label>
                    <input
                        type="text"
