const ItemType = {
    RESUME: "resume",
    COMPANY: "company",
    PROJECT: "project",
};

const ValidationMessageType = {
    OK: "ok",
    WARNING: "warning",
    ERROR: "error",
};

// Utility functions for general type checks
const isUndefined = (value) => value === undefined;
const isObject = (value) => typeof value === "object" && !isUndefined(value);
const isObjectButNotArray = (value) => isObject(value) && !Array.isArray(value);
const isString = (value) => typeof value === "string" && !isUndefined(value);
const isArray = (value) => Array.isArray(value);
const hasValidFields = (obj, fields) =>
    fields.every((field) => obj.hasOwnProperty(field) && isString(obj[field]));

// Utility function for deep validation
const validateFields = (obj, fieldDefs, parentFieldName = '') => {
    const messages = [];
    let isValid = true;

    fieldDefs.forEach(({ field, type, isRequired, nestedValidation }) => {
        const value = obj[field];

        if (isRequired && isUndefined(value)) {
            isValid = false;
            messages.push({
                type: ValidationMessageType.ERROR,
                message: `Missing required field: ${parentFieldName ? parentFieldName + '.' : ''}${field}`,
            });
            return;
        }

        if (type === "string" && !isString(value)) {
            isValid = false;
            messages.push({
                type: ValidationMessageType.ERROR,
                message: `Field ${parentFieldName ? parentFieldName + '.' : ''}'${field}' should be a string.`,
            });
        } else if (type === "object" && !isObjectButNotArray(value)) {
            isValid = false;
            messages.push({
                type: ValidationMessageType.ERROR,
                message: `Field ${parentFieldName ? parentFieldName + '.' : ''}'${field}' should be an object.`,
            });
        } else if (type === "array" && !isArray(value)) {
            isValid = false;
            messages.push({
                type: ValidationMessageType.ERROR,
                message: `Field ${parentFieldName ? parentFieldName + '.' : ''}'${field}' should be an array.`,
            });
        }

        // Recursive validation for nested structures
        if (nestedValidation && isObject(value)) {
            const nestedResults = nestedValidation(value, field);
            isValid = isValid && nestedResults.isValid;
            messages.push(...nestedResults.messages);
        }
    });

    return { isValid, messages };
};

// Specific validation functions for nested types
// const validateProcessedDetails = (details, parentFieldName) =>
//     validateFields(details, [
//         { field: "rawText", type: "string", isRequired: true },
//         { field: "textType", type: "string", isRequired: true },
//         { field: "metadata", type: "object", isRequired: true },
//     ], parentFieldName);

const validateDataForType = (data, type) => {
    if (!Object.values(ItemType).includes(type)) {
        return {
            isValid: false,
            messages: [
                {
                    type: ValidationMessageType.ERROR,
                    message: `Invalid type provided: ${type}`,
                },
            ],
        };
    }

    const { isValid, messages } = validateFields(data, [
        { field: "uniqueId", type: "string", isRequired: true },
        { field: "name", type: "string", isRequired: true },
        {
            field: "processedDetails",
            type: "object",
            isRequired: true,
            nestedValidation: (details, parentFieldName) =>
                validateFields(details, [
                    { field: "rawText", type: "string", isRequired: true },
                    { field: "textType", type: "string", isRequired: true },
                    { field: "metadata", type: "object", isRequired: true, 
                        nestedValidation:(metadata, pf)=> validateFields(metadata,[
                            {field:"summarizedIntroduction", type: "array", isRequired: true}
                        ], pf) },
                ], parentFieldName),
        },
    ]);

    return {
        validData: isValid,
        messages: messages.length
            ? messages
            : [
                {
                    type: ValidationMessageType.OK,
                    message: "All data validated successfully",
                },
            ],
    };
};

// Additional utility functions for expanded validations
const isValidItemType = (type) => Object.values(ItemType).includes(type);
const hasRequiredKeys = (obj, keys) => keys.every((key) => key in obj);
const hasNonEmptyStringValues = (obj, keys) =>
    keys.every((key) => isString(obj[key]) && obj[key].length > 0);

export {
    ItemType,
    validateDataForType,
    ValidationMessageType,
    isUndefined,
    isObject,
    isString,
    isArray,
    isValidItemType,
    hasRequiredKeys,
    hasNonEmptyStringValues,
    hasValidFields
};

