const UPSERT_RESUME = gql`
  mutation UpsertResume($resume: ResumeInput!) {
    upsertResume(resume: $resume) {
      uniqueId
      introduction
      summary
      companies {
        uniqueId
        name
        details
        projects {
          uniqueId
          name
          details
        }
      }
      educations {
        uniqueId
        name
        details
      }
    }
  }
`;

