import React, { useState } from 'react';

const withCollapse = (WrappedComponent) => {
  const WithCollapse = ({ headerText, ...props }) => {
    const [isCollapsed, setIsCollapsed] = useState(true);

    const toggleCollapse = () => {
      setIsCollapsed(!isCollapsed);
