The error indicates that `fieldDefs` is not recognized as an array when `validateFields` is called. Since `.bind()` does not directly pass arguments to a function until it’s invoked, it’s likely causing `fieldDefs` to be `undefined` within the bound context.

To resolve this, we should pass `fieldDefs` explicitly during each call rather than binding it. Here’s the corrected approach:

```javascript
const ItemType = {
    RESUME: "resume",
    COMPANY: "company",
    PROJECT: "project",
};

const ValidationMessageType = {
    OK: "ok",
    WARNING: "warning",
    ERROR: "error",
};

// Utility functions for general type checks
const isUndefined = (value) => value === undefined;
const isObject = (value) => typeof value === "object" && !isUndefined(value);
const isString = (value) => typeof value === "string" && !isUndefined(value);
const isArray = (value) => Array.isArray(value);

// Utility function for deep validation
const validateFields = (obj, fieldDefs, parentField = '') => {
    const messages = [];
    let isValid = true;

    fieldDefs.forEach(({ field, type, isRequired, nestedValidation }) => {
        const value = obj[field];
        const fieldName = parentField ? `${parentField}.${field}` : field;

        // Handle required fields
        if (isRequired && isUndefined(value)) {
            isValid = false;
            messages.push({
                type: ValidationMessageType.ERROR,
                message: `Missing required field: ${fieldName}`,
            });
            return;
        }

        // Validate field type
        const typeValidation = {
            string: isString,
            object: isObject,
            array: isArray,
        }[type];

        if (typeValidation && !typeValidation(value)) {
            isValid = false;
            messages.push({
                type: ValidationMessageType.ERROR,
                message: `Field '${fieldName}' should be a ${type}.`,
            });
        }

        // Apply nested validation
        if (nestedValidation && isObject(value)) {
            const nestedResults = nestedValidation(value, fieldName);
            isValid = isValid && nestedResults.isValid;
            messages.push(...nestedResults.messages);
        }
    });

    return { isValid, messages };
};

// Specific nested validations, now directly invoking validateFields with the field definitions
const validateMetadata = (metadata, parentField) =>
    validateFields(metadata, [
        { field: "summarizedIntroduction", type: "array", isRequired: true },
    ], parentField);

const validateProcessedDetails = (details, parentField) =>
    validateFields(details, [
        { field: "rawText", type: "string", isRequired: true },
        { field: "textType", type: "string", isRequired: true },
        { field: "metadata", type: "object", isRequired: true, nestedValidation: validateMetadata }
    ], parentField);

// Main data validation function
const validateDataForType = (data, type) => {
    if (!Object.values(ItemType).includes(type)) {
        return {
            isValid: false,
            messages: [
                {
                    type: ValidationMessageType.ERROR,
                    message: `Invalid type provided: ${type}`,
                },
            ],
        };
    }

    const { isValid, messages } = validateFields(data, [
        { field: "uniqueId", type: "string", isRequired: true },
        { field: "name", type: "string", isRequired: true },
        {
            field: "processedDetails",
            type: "object",
            isRequired: true,
            nestedValidation: validateProcessedDetails
        },
    ]);

    return {
        validData: isValid,
        messages: messages.length
            ? messages
            : [{ type: ValidationMessageType.OK, message: "All data validated successfully" }],
    };
};

// Exporting utilities
export {
    ItemType,
    validateDataForType,
    ValidationMessageType,
    isUndefined,
    isObject,
    isString,
    isArray
};
```

### Explanation
