import React, { useState, useEffect } from 'react';
import { useQuery, gql } from '@apollo/client';
import ResumeForm from './ResumeForm';

// GraphQL query to fetch all resumes
const GET_RESUMES = gql`
  query GetResumes {
    getAllResumes {
      uniqueId
      introduction
      summary
      companies {
        uniqueId
        name
        details
        projects {
          uniqueId
          name
          details
        }
      }
      educations {
        uniqueId
        name
        details
      }
    }
  }
`;

const ResumeDashboard = () => {
  // Use useQuery hook to execute the GET_RESUMES query
  const { loading, error, data } = useQuery(GET_RESUMES);

  // State to store list of resumes
  const [resumes, setResumes] = useState([]);

  // Update resumes state when data changes
  useEffect(() => {
    if (data && data.getAllResumes) {
      setResumes(data.getAllResumes);
    }
  }, [data]);

  // Function to add a new resume to the list
  const addResume = (newResume) => {
    setResumes([...resumes, newResume]);
  };

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Error fetching resumes: {error.message}</p>;

  return (
    <div>
      <h2>Create New Resume</h2>
      <ResumeForm addResume={addResume} />

      <h2>All Resumes</h2>
      <ul>
        {resumes.map((resume) => (
          <li key={resume.uniqueId}>
            <h3>{resume.introduction}</h3>
            <p>{resume.summary}</p>
            <h4>Companies</h4>
