                  <p>{company.details}</p>
                  <h5>Projects</h5>
                  <ul>
                    {company.projects.map((project) => (
                      <li key={project.uniqueId}>
                        <h5>{project.name}</h5>
                        <p>{project.details}</p>
                      </li>
                    ))}
                  </ul>
                </li>
              ))}
            </ul>
            <h4>Educations</h4>
            <ul>
              {resume.educations.map((education) => (
                <li key={education.uniqueId}>
                  <h4>{education.name}</h4>
                  <p>{education.details}</p>
                </li>
              ))}
            </ul>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default ResumeDashboard;
```

