If you want to keep both the `id` field with BSON data and the `_id` field visible in the document, you can do so by adding a separate `id` field for BSON data while retaining the default `_id` field in the Mongoose schema. Here's how you can achieve this:

```javascript
const mongoose = require('mongoose');
const { v4: uuidv4 } = require('uuid');

const taskSchema = new mongoose.Schema({
  id: {
    type: String,
    default: uuidv4,
    unique: true,
  },
  title: String,
  description: String,
  createdDate: {
    type: Date,
    default: Date.now,
  },
  updatedDate: {
    type: Date,
    default: Date.now,
  },
});

// Middleware to update the 'updatedDate' field before each 'update' operation
taskSchema.pre('update', function (next) {
  this.updatedDate = new Date();
  next();
});

// Keep the default _id field in the schema
