  _id: mongoose.Types.ObjectId,
});

module.exports = mongoose.model('Task', taskSchema);
```

In this code:

- We've added the `id` field with BSON data using `mongoose.Types.ObjectId` to the schema definition. This will create an `id` field containing BSON data in your MongoDB documents.

- We've retained the default `_id` field, which is also generated by MongoDB.

Now, when you create a new `Task` document, it will have both the `id` field with BSON data and the `_id` field visible in the document.

