To add a login REST endpoint in your user routes, you can modify your existing user routes file (e.g., `userroutes.js`). Here's an example of how to create a login endpoint using Express.js and MongoDB:

```javascript
const express = require('express');
const router = express.Router();
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const User = require('../models/User'); // Assuming you have a User model

// POST /api/users/login - User login endpoint
router.post('/login', async (req, res) => {
  try {
    // Check if the username exists
    const user = await User.findOne({ username: req.body.username });

    if (!user) {
      return res.status(401).json({ message: 'Invalid username or password' });
    }

    // Compare the provided password with the stored hashed password
    const passwordMatch = await bcrypt.compare(req.body.password, user.password);

    if (!passwordMatch) {
      return res.status(401).json({ message: 'Invalid username or password' });
    }

    // If the username and password are correct, generate a JWT token
    const token = jwt.sign({ userId: user._id }, 'your-secret-key', { expiresIn: '1h' });

    // Send the token in the response
    res.status(200).json({ token });
  } catch (error) {
    console.error('Login error:', error);
    res.status(500).json({ message: 'An error occurred during login' });
  }
});

module.exports = router;
```

In this code:

1. We create a `/login` endpoint that accepts POST requests.

2. We first check if a user with the provided username exists in the database. If not, we return a 401 Unauthorized response.

3. If the user exists, we use `bcrypt` to compare the provided password with the stored hashed password. If they match, we proceed.

4. We then generate a JWT token using the `jsonwebtoken` library. You should replace `'your-secret-key'` with a strong secret key for your application.

5. Finally, we send the generated token in the response.

Make sure to include this user routes file in your main Express application, and it will handle user logins via the `/api/users/login` endpoint. You can adjust the error handling and response messages as needed for your application.

