```jsx
// resumeSlice.js

import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import axios from 'axios';

// Define the initial state for the resume slice
const initialState = {
  resumes: [], // Holds the list of resumes for the upsert API
  selectedResume: null, // Holds the selected resume for the get API
  status: 'idle', // Possible values: 'idle', 'loading', 'succeeded', 'failed'
  error: null, // Holds any error that occurs during API calls
};

// Define an async thunk for the upsert API
export const upsertResumes = createAsyncThunk('resume/upsert', async (resumes) => {
  const response = await axios.post('/api/my-resume/upsert', resumes);
  return response.data;
});

// Define an async thunk for the get API
export const getResumeByUniqueId = createAsyncThunk('resume/get', async (uniqueId) => {
  const response = await axios.get(`/api/my-resume/get?uniqueId=${uniqueId}`);
  return response.data;
});

// Create the resume slice using createSlice
const resumeSlice = createSlice({
  name: 'resume',
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    // Handle the pending state for both thunks
    builder.addCase(upsertResumes.pending, (state) => {
      state.status = 'loading';
    });
    builder.addCase(getResumeByUniqueId.pending, (state) => {
      state.status = 'loading';
    });

    // Handle the fulfilled state for both thunks
    builder.addCase(upsertResumes.fulfilled, (state, action) => {
      state.status = 'succeeded';
      state.resumes = action.payload;
    });
    builder.addCase(getResumeByUniqueId.fulfilled, (state, action) => {
      state.status = 'succeeded';
      state.selectedResume = action.payload;
    });

    // Handle the rejected state for both thunks
    builder.addCase(upsertResumes.rejected, (state, action) => {
      state.status = 'failed';
      state.error = action.error.message;
    });
    builder.addCase(getResumeByUniqueId.rejected, (state, action) => {
      state.status = 'failed';
      state.error = action.error.message;
    });
  },
});

// Export the async thunks for use in components or other parts of the application
export { upsertResumes, getResumeByUniqueId };

// Export the reducer to be used in the Redux store
export default resumeSlice.reducer;
```

