public class DataCategory extends AuditableEntity implements Serializable, Cloneable {
    private static final long serialVersionUID = 1L;

    @Indexed(unique = true)
    @Field("categoryKey")
    private String categoryKey;
    @Field("categoryName")
    private String categoryName;
    @Field("categoryDesc")
    private String categoryDesc;
    @Field("esgType")
    private ESGEnums esgType;
    @Field("scopeType")
    private ESGEnums scopeType;
    @Field("categoryType")
    private ESGEnums categoryType;
    @Field("scopeLinkage")
    private List<String> scopeLinkage;

    @Field("active")
    private Boolean active;
    @Version
    @Field("version")
    private Integer version;

    @Field("defaultLanguage")
    private String defaultLanguage;
    @Field("translation")
    private List<Locale> translation;

    @Field("linkedDataModel")
    private LinkedHashSet<LinkedDataModel> linkedDataModels;

    @Field("awsProjectURL")
    private String awsProjectURL;

    @Data
    @AllArgsConstructor
    @NoArgsConstructor
    public class LinkedDataModel implements Serializable {
        public LinkedDataModel(ObjectId id, String attributeKey, int sequenceOrder) {
            this.attributeId = id;
            this.attributeKey = attributeKey;
            this.sequenceOrder = sequenceOrder;
        }
        @Field("attributeId")
        private ObjectId attributeId;
        @Field("attributeKey")
        private String attributeKey;
        @Field("sequenceOrder")
        private int sequenceOrder;
        @Field("dataFilePath")
        private String dataFilePath;
        @Field("dataModelPath")
        private String dataModelPath;
        @Field("dataModelAttributePath")
        private String dataModelAttributePath;
    }

    public void addDataModels(List<LinkedDataModelDto> linkedDataModelDtos, List<Attribute> attributes) {
        if (CollectionUtils.isEmpty(attributes))
            return;

        linkedDataModels = new LinkedHashSet<>();
        for (LinkedDataModelDto linkedDataModelDto : linkedDataModelDtos) {
            attributes.stream()
                    .filter(attribute -> attribute.getAttributeKey().equals(linkedDataModelDto.getAttributeKey()))
                    .forEach(attribute -> linkedDataModels.add(new LinkedDataModel(attribute.getId(),
                            attribute.getAttributeKey(), linkedDataModelDto.getSequenceOrder())));
        }
    }

    public void addLocale(Locale locale) {
        if (locale == null)
            return;
        translation = translation != null ? translation : new ArrayList<>();
        translation.add(locale);
    }

    @Builder
    public DataCategory(ObjectId id, String createdBy, LocalDateTime createdDate, String lastModifiedBy,
            LocalDateTime lastModifiedDate, String tenantId, String categoryKey, String categoryName,
            String categoryDesc, ESGEnums esgType, ESGEnums scopeType, ESGEnums categoryType, List<String> scopeLinkage,
