    let task = await Task.findById(taskId);

    // Check if the task exists
    if (!task) {
      return res.status(404).json({ message: "Task not found" });
    }

    // Update the parentId of children tasks
    const childrenIds = updatedTask.children || [];
    await Task.updateMany({ _id: { $in: childrenIds } }, { parentId: taskId });

    res.json({ message: "ParentId updated successfully for children tasks" });
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
});
```

In this code:
- We first find the existing task with the given `taskId`.
- Then, we extract the `children` array from the `updatedTask` object.
- We use the `updateMany` method to update the `parentId` of all children tasks whose IDs are present in the `children` array to the `taskId`.

