const mongoose = require('mongoose');
const Topic = require('./path_to_your_topic_model'); // Adjust the path to your Topic model

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(bodyParser.json());

// MongoDB connection
