import React, { Component } from 'react';

class DynamicForm extends Component {
  constructor(props) {
    super(props);

    this.state = {
      fields: [{ value: '' }],
    };
  }

  // Function to handle adding a new input field
  addField = () => {
    const { fields } = this.state;
    this.setState({
      fields: [...fields, { value: '' }],
    });
  };

  // Function to handle removing an input field
  removeField = (index) => {
    const { fields } = this.state;
    fields.splice(index, 1);
    this.setState({
      fields: [...fields],
    });
  };

  // Function to handle input value change
  handleInputChange = (index, event) => {
    const { fields } = this.state;
    fields[index].value = event.target.value;
    this.setState({
      fields: [...fields],
    });
  };

  // Function to submit the form data (you can customize this)
  handleSubmit = (event) => {
    event.preventDefault();
    console.log('Form Data:', this.state.fields);
  };

  render() {
    const { fields } = this.state;

    return (
      <div>
        <form onSubmit={this.handleSubmit}>
          {fields.map((field, index) => (
            <div key={index}>
              <input
                type="text"
                value={field.value}
                onChange={(e) => this.handleInputChange(index, e)}
              />
              <button type="button" onClick={() => this.removeField(index)}>
                Remove
              </button>
            </div>
          ))}
          <button type="button" onClick={this.addField}>
            Add Field
          </button>
          <button type="submit">Submit</button>
        </form>
      </div>
    );
  }
}

export default DynamicForm;
```

In this example, we create a `DynamicForm` component that maintains an array of input fields in its state. Users can add new fields by clicking the "Add Field" button and remove fields using the "Remove" buttons next to each input. The form data is logged to the console when the user submits the form. You can customize the `handleSubmit` function to handle the form data according to your requirements.

